/**
 * Demo seed for the LBE CRM. Called by src/db/index.ts when the users table is empty.
 *
 * - Item master + BOQ templates come from the client's Excel files (see seed-data/*.ts, generated by
 *   work/scripts/build_seed.py). Items flagged demoPrice carry a DEMO ASSUMPTION list price (client to confirm).
 * - Business data (customers, quotes, POs, invoices, …) is fictional and generated with a seeded PRNG,
 *   so it is deterministic EXCEPT that every date is computed relative to "today" so the demo always looks current.
 * - No transaction (works the same on PGlite and Neon). Inserts are batched in chunks of 200.
 */
import { hashSync } from "bcryptjs";
import { eq } from "drizzle-orm";
import type { DB } from "./index";
import * as s from "./schema";
import { SEED_ITEMS, type SeedItem } from "./seed-data/items";
import { SEED_TEMPLATES } from "./seed-data/boq-templates";
import { KICKOFF_TRANSCRIPT } from "./seed-data/meeting-transcript";
import {
  AGENT_RULES, COMPANY_SETTINGS, DEMO_CUSTOMERS, DEMO_VENDORS, KICKOFF_NOTE, PRICING_SETTINGS,
} from "./seed-data/demo";

// ------------------------------------------------------------------ helpers
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const round2 = (n: number) => Math.round((n + Number.EPSILON) * 100) / 100;
const pad = (n: number, w = 2) => String(n).padStart(w, "0");

async function batched<R, O>(rows: R[], fn: (chunk: R[]) => Promise<O[]>, size = 200): Promise<O[]> {
  const out: O[] = [];
  for (let i = 0; i < rows.length; i += size) {
    const chunk = rows.slice(i, i + size);
    if (chunk.length) out.push(...(await fn(chunk)));
  }
  return out;
}

type ItemRec = SeedItem & { id: number };

export async function seed(db: DB): Promise<void> {
  const rng = mulberry32(20261120);
  const rand = (a: number, b: number) => a + (b - a) * rng();
  const randInt = (a: number, b: number) => Math.floor(rand(a, b + 1));
  const pick = <T,>(arr: readonly T[]): T => arr[Math.floor(rng() * arr.length)];

  // ---------------------------------------------------------------- dates (relative to today)
  const now = new Date();
  const T0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const ymd = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const parse = (str: string) => {
    const [y, m, d] = str.split("-").map(Number);
    return new Date(y, m - 1, d);
  };
  const day = (offset: number) => ymd(new Date(T0.getFullYear(), T0.getMonth(), T0.getDate() + offset));
  const ago = (n: number) => day(-n);
  const addDays = (str: string, n: number) => {
    const d = parse(str);
    return ymd(new Date(d.getFullYear(), d.getMonth(), d.getDate() + n));
  };
  const addMonths = (str: string, n: number) => {
    const d = parse(str);
    return ymd(new Date(d.getFullYear(), d.getMonth() + n, d.getDate()));
  };
  const at = (str: string, hour = 11) => {
    const d = parse(str);
    d.setHours(hour, 0, 0, 0);
    return d;
  };
  const daysAgoOf = (str: string) => Math.round((T0.getTime() - parse(str).getTime()) / 86400000);
  const fy = (str: string) => {
    const d = parse(str);
    const start = d.getMonth() >= 3 ? d.getFullYear() : d.getFullYear() - 1;
    return `${start}-${pad((start + 1) % 100)}`;
  };
  const minDate = (a: string, b: string) => (a < b ? a : b);

  // document numbering → also written to the sequences table at the end
  const seq = new Map<string, number>();
  const nextSeq = (key: string) => {
    const v = (seq.get(key) ?? 0) + 1;
    seq.set(key, v);
    return v;
  };

  // ---------------------------------------------------------------- users
  const pw = hashSync("Demo@123", 10);
  const userDefs = [
    { key: "admin", name: "Karthick (Owner)", email: "admin@lbe.demo", role: "admin", phone: "+91 9442000101" },
    { key: "sales", name: "Priya Sundaram", email: "sales@lbe.demo", role: "sales", phone: "+91 9442000102" },
    { key: "purchase", name: "Ramesh Kannan", email: "purchase@lbe.demo", role: "purchase", phone: "+91 9442000103" },
    { key: "accounts", name: "Lakshmi Narayanan", email: "accounts@lbe.demo", role: "accounts", phone: "+91 9442000104" },
    { key: "engineer", name: "Senthil Kumar (Site Engineer)", email: "engineer@lbe.demo", role: "engineer", phone: "+91 9442000105" },
    { key: "engineer2", name: "Arun Prakash (Site Engineer)", email: "engineer2@lbe.demo", role: "engineer", phone: "+91 9442000106" },
    { key: "store", name: "Murali (Stores)", email: "store@lbe.demo", role: "store", phone: "+91 9442000107" },
  ];
  const userIds = await db.insert(s.users)
    .values(userDefs.map((u) => ({ name: u.name, email: u.email, role: u.role, phone: u.phone, passwordHash: pw })))
    .returning({ id: s.users.id });
  const U: Record<string, number> = {};
  userDefs.forEach((u, i) => (U[u.key] = userIds[i].id));

  // ---------------------------------------------------------------- settings & agent rules
  await db.insert(s.settings).values([
    { key: "company", value: COMPANY_SETTINGS },
    { key: "pricing", value: PRICING_SETTINGS },
  ]);
  await db.insert(s.agentRules).values(AGENT_RULES.map((r) => ({ agent: r.agent, enabled: true, params: r.params })));

  // ---------------------------------------------------------------- items
  const itemRows: (typeof s.items.$inferInsert)[] = SEED_ITEMS.map((it) => ({
    code: it.code, name: it.name, system: it.system, groupName: it.groupName, size: it.size, make: it.make,
    uom: it.uom, hsn: it.hsn, gstRate: it.gstRate, description: it.description, listPrice: it.listPrice,
    markupPct: it.markupPct, erectionRate: it.erectionRate, reorderLevel: it.reorderLevel, volatilePrice: it.volatilePrice,
  }));
  const itemIds = await batched(itemRows, (c) => db.insert(s.items).values(c).returning({ id: s.items.id }));
  const ITEM = new Map<string, ItemRec>();
  const ITEM_BY_ID = new Map<number, ItemRec>();
  SEED_ITEMS.forEach((it, i) => {
    const rec = { ...it, id: itemIds[i].id };
    ITEM.set(it.code, rec);
    ITEM_BY_ID.set(rec.id, rec);
  });
  const item = (code: string): ItemRec => {
    const it = ITEM.get(code);
    if (!it) throw new Error(`seed: unknown item code ${code}`);
    return it;
  };

  // list price history (price list dated ~40 days ago)
  const listDate = ago(40);
  await batched(
    SEED_ITEMS.filter((it) => it.listPrice != null).map((it) => ({
      itemId: item(it.code).id, kind: "list", rate: it.listPrice as number, date: listDate, refType: "manual",
    })),
    (c) => db.insert(s.priceHistory).values(c).returning({ id: s.priceHistory.id }),
  );

  /** Procurement cost model: list price is "today's" market cost; pipes/cables rise ~1%/month, others ~7%/yr. */
  const costAt = (it: SeedItem, daysAgo: number, vendorFactor = 1, noise = 0) => {
    const lp = it.listPrice ?? 0;
    const months = Math.max(0, daysAgo) / 30.44;
    const trend = it.volatilePrice ? Math.pow(1.01, -months) : Math.pow(1.07, -months / 12);
    return round2(lp * 0.97 * trend * vendorFactor * (1 + noise));
  };
  const sellAt = (it: SeedItem, daysAgo: number, markup = it.markupPct) => Math.round(costAt(it, daysAgo) * (1 + markup / 100));

  // ---------------------------------------------------------------- BOQ templates
  const tplIds = await db.insert(s.boqTemplates)
    .values(SEED_TEMPLATES.map((t) => ({ name: t.name, system: t.system, description: t.description })))
    .returning({ id: s.boqTemplates.id });
  const TPL = new Map<string, { id: number; t: (typeof SEED_TEMPLATES)[number] }>();
  SEED_TEMPLATES.forEach((t, i) => TPL.set(t.key, { id: tplIds[i].id, t }));
  await batched(
    SEED_TEMPLATES.flatMap((t) => t.lines.map((l) => ({
      templateId: TPL.get(t.key)!.id, sortOrder: l.sortOrder, boqRef: l.boqRef, section: l.section,
      itemId: l.itemCode ? item(l.itemCode).id : null, description: l.description, uom: l.uom, defaultQty: l.defaultQty,
    }))),
    (c) => db.insert(s.boqTemplateLines).values(c).returning({ id: s.boqTemplateLines.id }),
  );

  // ---------------------------------------------------------------- customers & vendors
  const custIds = await db.insert(s.customers).values(DEMO_CUSTOMERS.map((c) => ({
    name: c.name, contactPerson: c.contactPerson, phone: c.phone, email: c.email, gstin: c.gstin, address: c.address,
    city: c.city, state: c.state, type: c.type, paymentTermsDays: c.paymentTermsDays, creditLimit: c.creditLimit, notes: c.notes ?? null,
  }))).returning({ id: s.customers.id });
  const C = (i: number) => custIds[i].id;
  const vendIds = await db.insert(s.vendors).values(DEMO_VENDORS.map((v) => ({
    name: v.name, contactPerson: v.contactPerson, phone: v.phone, email: v.email, gstin: v.gstin, address: v.address,
    city: v.city, systems: v.systems, paymentTermsDays: v.paymentTermsDays, notes: v.notes ?? null,
  }))).returning({ id: s.vendors.id });
  const V = new Map<string, { id: number; v: (typeof DEMO_VENDORS)[number] }>();
  DEMO_VENDORS.forEach((v, i) => V.set(v.key, { id: vendIds[i].id, v }));

  // ---------------------------------------------------------------- quotations
  type QLine = {
    sortOrder: number; boqRef: string | null; section: string | null; itemId: number | null; description: string;
    qty: number; uom: string; costRate: number; supplyRate: number; erectionRate: number; remarks: string | null;
  };
  const qtyFor = (it: SeedItem | null, uom: string, desc: string) => {
    if (uom === "Mtr") return randInt(4, 50) * 6;
    if (uom === "Kg") return randInt(4, 16) * 50;
    if (uom === "LS" || uom === "Set") return 1;
    const p = it?.listPrice ?? 0;
    if (p >= 100000) return 1;
    if (p >= 20000) return randInt(1, 3);
    if (it && /Detector|Base|Response Indicator|Sprinkler|Back box/i.test(it.groupName)) return randInt(4, 30) * 5;
    if (/sprinkler/i.test(desc)) return randInt(10, 60) * 5;
    return randInt(2, 16);
  };
  function buildLines(tplKey: string, daysAgo: number, maxLines: number, opts: { useDefaults?: boolean; markup?: number } = {}): QLine[] {
    const { t } = TPL.get(tplKey)!;
    let src = t.lines.filter((l) => !opts.useDefaults || l.defaultQty > 0);
    if (src.length > maxLines) {
      // deterministic subset keeping original order, biased to item-linked lines
      const scored = src.map((l, i) => ({ l, i, k: rng() + (l.itemCode ? 0.35 : 0) }));
      src = scored.sort((a, b) => b.k - a.k).slice(0, maxLines).sort((a, b) => a.i - b.i).map((x) => x.l);
    }
    return src.map((l, i) => {
      const it = l.itemCode ? item(l.itemCode) : null;
      let qty = opts.useDefaults ? Math.max(1, Math.round(l.defaultQty * rand(0.7, 1.4))) : qtyFor(it, l.uom, l.description);
      if (opts.useDefaults && l.uom === "Mtr") qty = Math.max(6, Math.round(qty / 6) * 6);
      let costRate = 0, supplyRate = 0, erectionRate = 0;
      if (it) {
        costRate = costAt(it, daysAgo);
        supplyRate = Math.round(costRate * (1 + (opts.markup ?? it.markupPct) / 100));
        erectionRate = it.erectionRate;
      } else {
        // free-text (labour / dismantling / termination) line priced manually: erection only
        erectionRate = Math.round(rand(150, 2500) / 10) * 10;
        costRate = round2(erectionRate * 0.6);
      }
      return {
        sortOrder: i + 1, boqRef: l.boqRef, section: l.section, itemId: it?.id ?? null, description: l.description,
        qty, uom: l.uom, costRate, supplyRate, erectionRate, remarks: null,
      };
    });
  }
  const totals = (lines: QLine[], discountPct: number, gstPct: number) => {
    const subtotalSupply = round2(lines.reduce((a, l) => a + l.qty * l.supplyRate, 0));
    const subtotalErection = round2(lines.reduce((a, l) => a + l.qty * l.erectionRate, 0));
    const discount = round2(((subtotalSupply + subtotalErection) * discountPct) / 100);
    const net = round2(subtotalSupply + subtotalErection - discount);
    const taxAmount = round2((net * gstPct) / 100);
    return {
      subtotalSupply, subtotalErection, net, taxAmount, grandTotal: round2(net + taxAmount),
      costTotal: round2(lines.reduce((a, l) => a + l.qty * l.costRate, 0)),
    };
  };

  type QSpec = {
    key: string; cust: number; tpl: string; status: string; daysAgo: number; project: string; site: string;
    maxLines?: number; discount?: number; markup?: number; next?: number | null; followUps?: number; lostReason?: string; notes?: string;
  };
  const QSPECS: QSpec[] = [
    { key: "w1", cust: 0, tpl: "hs1", status: "won", daysAgo: 300, project: "Hydrant & Sprinkler System, New Press Shop", site: "SIPCOT Phase I, Hosur", maxLines: 22, discount: 3, followUps: 3 },
    { key: "w2", cust: 11, tpl: "fa1", status: "won", daysAgo: 210, project: "Addressable Fire Alarm & PA, Plant 2", site: "Mathigiri, Hosur", maxLines: 14, discount: 2, followUps: 2 },
    { key: "w3", cust: 1, tpl: "hs2", status: "won", daysAgo: 170, project: "Sprinkler Modification, Fettling Shop", site: "SIPCOT Phase II, Hosur", maxLines: 14, followUps: 2 },
    { key: "w4", cust: 4, tpl: "hsq", status: "won", daysAgo: 95, project: "Yard Hydrant Ring Main, Warehouse 3", site: "Attibele, Bengaluru", maxLines: 20, discount: 2.5, followUps: 3 },
    { key: "w5", cust: 5, tpl: "fa2", status: "won", daysAgo: 60, project: "8-Loop Networked Fire Alarm, Tower B", site: "Electronic City Phase II, Bengaluru", maxLines: 12, followUps: 2 },
    { key: "w6", cust: 8, tpl: "exn", status: "won", daysAgo: 45, project: "Fire Extinguisher Supply, New Moulding Unit", site: "Zuzuvadi, Hosur", followUps: 1 },
    { key: "l1", cust: 2, tpl: "hsq", status: "lost", daysAgo: 120, project: "Hydrant System, Cold Storage", site: "Krishnagiri", maxLines: 18, lostReason: "Price higher than competitor by ~8%", followUps: 2 },
    { key: "l2", cust: 10, tpl: "fa1", status: "lost", daysAgo: 80, project: "Fire Alarm, Residential Block C", site: "Bommasandra, Bengaluru", maxLines: 10, lostReason: "Project deferred by client", followUps: 2 },
    { key: "x1", cust: 3, tpl: "exn", status: "expired", daysAgo: 70, project: "Extinguishers, Weaving Shed", site: "Shoolagiri", followUps: 1 },
    { key: "s1", cust: 6, tpl: "fa1", status: "sent", daysAgo: 20, project: "Fire Alarm Upgrade, OT & ICU Block", site: "Denkanikottai Road, Hosur", maxLines: 12, next: -3, followUps: 1 },
    { key: "s2", cust: 7, tpl: "exr", status: "sent", daysAgo: 10, project: "Annual Extinguisher Refilling", site: "Bagalur Road, Hosur", next: null, followUps: 0 },
    { key: "s3", cust: 9, tpl: "hs1", status: "sent", daysAgo: 28, project: "Hydrant & Sprinkler, Client: Pharma Unit (via consultant)", site: "Hosur", maxLines: 18, next: 0, followUps: 1 },
    { key: "s4", cust: 2, tpl: "hs2", status: "sent", daysAgo: 6, project: "Sprinkler Retrofit, Packing Hall", site: "Krishnagiri", maxLines: 12, next: 2, followUps: 1 },
    { key: "n1", cust: 0, tpl: "fa2", status: "negotiation", daysAgo: 35, project: "Networked Fire Alarm, Admin & Plant", site: "SIPCOT Phase I, Hosur", maxLines: 12, discount: 4, next: -1, followUps: 3 },
    { key: "n2", cust: 4, tpl: "exn", status: "negotiation", daysAgo: 18, project: "Extinguishers, Warehouse 3", site: "Attibele, Bengaluru", discount: 25, next: 1, followUps: 2, notes: "Client asking for 25% discount, check margin before confirming." },
    { key: "n3", cust: 11, tpl: "hsq", status: "negotiation", daysAgo: 25, project: "Hydrant Extension, New Stores Building", site: "Mathigiri, Hosur", maxLines: 18, discount: 5, next: 0, followUps: 2 },
    { key: "d1", cust: 5, tpl: "hs1", status: "draft", daysAgo: 3, project: "Pump House & Hydrant, Tower C", site: "Electronic City, Bengaluru", maxLines: 16 },
    { key: "d2", cust: 1, tpl: "exr", status: "draft", daysAgo: 1, project: "Extinguisher Refilling, FY renewal", site: "SIPCOT Phase II, Hosur" },
  ];
  const quickTpl = new Set(["hsq", "exn", "exr"]);
  type QBuilt = { spec: QSpec; quoteDate: string; lines: QLine[]; tot: ReturnType<typeof totals>; closedDate: string | null; id?: number; number?: string };
  const quotes: QBuilt[] = QSPECS.map((spec) => {
    const quoteDate = ago(spec.daysAgo);
    const lines = buildLines(spec.tpl, spec.daysAgo, spec.maxLines ?? 30, { useDefaults: quickTpl.has(spec.tpl), markup: spec.markup });
    const tot = totals(lines, spec.discount ?? 0, 18);
    const closedDate = spec.status === "won" || spec.status === "lost" ? addDays(quoteDate, 20)
      : spec.status === "expired" ? addDays(quoteDate, 31) : null;
    return { spec, quoteDate, lines, tot, closedDate };
  }).sort((a, b) => (a.quoteDate < b.quoteDate ? -1 : a.quoteDate > b.quoteDate ? 1 : 0));
  for (const q of quotes) {
    const f = fy(q.quoteDate);
    q.number = `LBE/Q/${f}/${pad(nextSeq(`quotation:${f}`), 4)}`;
  }
  const qIds = await db.insert(s.quotations).values(quotes.map((q) => {
    const sp = q.spec;
    const sent = sp.status !== "draft";
    return {
      number: q.number!, revision: sp.status === "negotiation" ? 1 : 0, customerId: C(sp.cust), projectName: sp.project,
      siteLocation: sp.site, system: TPL.get(sp.tpl)!.t.system, templateId: TPL.get(sp.tpl)!.id, status: sp.status,
      quoteDate: q.quoteDate, validUntil: addDays(q.quoteDate, 30), preparedBy: U.sales, markupPct: sp.markup ?? 40,
      discountPct: sp.discount ?? 0, gstPct: 18, subtotalSupply: q.tot.subtotalSupply, subtotalErection: q.tot.subtotalErection,
      costTotal: q.tot.costTotal, taxAmount: q.tot.taxAmount, grandTotal: q.tot.grandTotal, terms: COMPANY_SETTINGS.quoteTerms,
      notes: sp.notes ?? null,
      nextFollowUpDate: sp.status === "sent" || sp.status === "negotiation" ? (sp.next == null ? null : day(sp.next)) : null,
      lostReason: sp.lostReason ?? null, sentAt: sent ? at(addDays(q.quoteDate, 1), 15) : null,
      closedAt: q.closedDate ? at(q.closedDate, 17) : null,
    };
  })).returning({ id: s.quotations.id });
  quotes.forEach((q, i) => (q.id = qIds[i].id));
  const Q = new Map(quotes.map((q) => [q.spec.key, q]));

  await batched(
    quotes.flatMap((q) => q.lines.map((l) => ({ ...l, quotationId: q.id! }))),
    (c) => db.insert(s.quotationLines).values(c).returning({ id: s.quotationLines.id }),
  );

  // follow-ups
  const FU_NOTES = [
    ["call", "Spoke to client, they are reviewing the BOQ with their consultant.", "neutral"],
    ["email", "Sent revised technical compliance sheet and make list.", "positive"],
    ["whatsapp", "Shared datasheets for detectors / valves on WhatsApp.", "neutral"],
    ["visit", "Site visit with engineer; confirmed pipe routing and quantities.", "positive"],
    ["call", "Client not reachable; left message with purchase team.", "no_response"],
    ["meeting", "Commercial discussion: client requested better price on supply items.", "neutral"],
  ] as const;
  const fuRows: (typeof s.followUps.$inferInsert)[] = [];
  for (const q of quotes) {
    const n = q.spec.followUps ?? 0;
    const start = daysAgoOf(q.quoteDate) - 2;
    const end = q.closedDate ? daysAgoOf(q.closedDate) + 1 : 1;
    for (let k = 0; k < n; k++) {
      const da = Math.max(end, Math.round(start - ((start - end) * (k + 1)) / (n + 1)));
      const [mode, notes, outcome] = pick(FU_NOTES);
      const isLast = k === n - 1;
      const open = q.spec.status === "sent" || q.spec.status === "negotiation";
      fuRows.push({
        quotationId: q.id!, date: ago(da), mode, notes, outcome,
        nextDate: isLast && open ? (q.spec.next == null ? null : day(q.spec.next)) : ago(Math.max(0, da - 5)),
        userId: U.sales, createdAt: at(ago(da), 16),
      });
    }
    if (q.spec.status === "won") {
      fuRows.push({ quotationId: q.id!, date: q.closedDate!, mode: "meeting", notes: "PO confirmed by client.", outcome: "positive", userId: U.sales, createdAt: at(q.closedDate!, 17) });
    }
  }
  if (fuRows.length) await db.insert(s.followUps).values(fuRows);

  // quote price history for won quotes
  await batched(
    quotes.filter((q) => q.spec.status === "won").flatMap((q) => q.lines.filter((l) => l.itemId).map((l) => ({
      itemId: l.itemId!, kind: "quote", rate: l.supplyRate, date: q.closedDate!, customerId: C(q.spec.cust),
      refType: "quotation", refId: q.id!, qty: l.qty,
    }))),
    (c) => db.insert(s.priceHistory).values(c).returning({ id: s.priceHistory.id }),
  );

  // ---------------------------------------------------------------- projects (from won quotes w1..w5)
  type PSpec = { q: string; status: string; startAfterWon: number; durationDays: number; engineer: string };
  const PSPECS: PSpec[] = [
    { q: "w1", status: "completed", startAfterWon: 10, durationDays: 90, engineer: "engineer" },
    { q: "w2", status: "active", startAfterWon: 10, durationDays: 240, engineer: "engineer2" },
    { q: "w3", status: "active", startAfterWon: 10, durationDays: 180, engineer: "engineer" },
    { q: "w4", status: "active", startAfterWon: 10, durationDays: 120, engineer: "engineer2" },
    { q: "w5", status: "active", startAfterWon: 12, durationDays: 90, engineer: "engineer" },
  ];
  const projects = PSPECS.map((p) => {
    const q = Q.get(p.q)!;
    const startDate = addDays(q.closedDate!, p.startAfterWon);
    return { p, q, startDate, endDate: addDays(startDate, p.durationDays), id: 0, code: "" };
  }).sort((a, b) => (a.startDate < b.startDate ? -1 : 1));
  for (const pr of projects) {
    const y = parse(pr.startDate).getFullYear();
    pr.code = `PRJ-${y}-${pad(nextSeq(`project:${y}`), 3)}`;
  }
  const prIds = await db.insert(s.projects).values(projects.map((pr) => {
    const cust = DEMO_CUSTOMERS[pr.q.spec.cust];
    return {
      code: pr.code, name: pr.q.spec.project, customerId: C(pr.q.spec.cust), quotationId: pr.q.id!, status: pr.p.status,
      siteAddress: `${pr.q.spec.site}, ${cust.name}`, engineerId: U[pr.p.engineer], startDate: pr.startDate, endDate: pr.endDate,
      contractValue: pr.q.tot.net, budget: Math.round(pr.q.tot.net * 0.7),
      notes: pr.p.status === "completed" ? "Handed over; fire NOC obtained." : null,
    };
  })).returning({ id: s.projects.id });
  projects.forEach((pr, i) => (pr.id = prIds[i].id));
  const PRJ = new Map(projects.map((pr) => [pr.p.q, pr]));

  // ---------------------------------------------------------------- opening stock (fire alarm devices & extinguishers)
  const openingDate = ago(935);
  const OPENING: [string, number][] = [
    ["FA-SDA-RAV", 40], ["FA-HDA-RAV", 6], ["FA-MDA-RAV", 25], ["FA-BASE-RAV", 60], ["FA-MCP-RAV", 3], ["FA-HTR-RAV", 12],
    ["FA-SD-RAV", 30], ["FA-HD-RAV", 14], ["FA-SDA-HON", 12], ["FA-RI-STD", 25], ["FA-BBX-STD", 80],
    ["EXN-ABC6-SFX", 24], ["EXN-ABC4-SFX", 15], ["EXN-CO245-SFX", 8], ["EXN-CO245-CHK", 2], ["EXN-ABC9-CHK", 3],
    ["EXN-ABC6-CHK", 10], ["EXN-CO22-CHK", 6], ["EXN-CA2-SFX", 4], ["EXN-CO29-SFX", 6], ["SP-WSH", 40], ["SP-NOZ", 6],
    ["SP-ZBA", 30], ["SP-ZBC", 20], ["SP-STD", 10],
  ];
  const stockRows: (typeof s.stockMovements.$inferInsert)[] = OPENING.map(([code, qty]) => ({
    itemId: item(code).id, qty, type: "opening", rate: costAt(item(code), 935), date: openingDate,
    notes: "Opening stock", createdBy: U.store, createdAt: at(openingDate, 10),
  }));

  // ---------------------------------------------------------------- purchase invoices (~40 over 30 months)
  const POOLS: Record<string, { vendors: string[]; items: string[]; projSystems: string[] }> = {
    pipes: { vendors: ["pipes1", "pipes2"], items: ["HS-PGI-25", "HS-PGI-32", "HS-PGI-40", "HS-PGI-50", "HS-PGI-65", "HS-PGI-80", "HS-PGI-100", "HS-PGI-150", "HS-PMS-50", "HS-PMS-80", "HS-PMS-100", "HS-PMS-150", "HS-PMS-200", "HS-EGI-100", "HS-EGI-150", "HS-CCH-100x50"], projSystems: ["hydrant_sprinkler"] },
    valves: { vendors: ["valves1", "hydrant1"], items: ["HS-BFV-80", "HS-BFV-100", "HS-BFV-150", "HS-NRV-100", "HS-NRV-150", "HS-GV-150", "HS-YS-100", "HS-YS-150", "HS-BV-25", "HS-BV-50"], projSystems: ["hydrant_sprinkler"] },
    hydrant: { vendors: ["hydrant1", "pipes2"], items: ["HS-SPR-PEN", "HS-SPR-UPR", "HS-SHV", "HS-RRL", "HS-BRP", "HS-HRD", "HS-PG", "HS-CPL-50", "HS-CPL-100", "HS-HBS"], projSystems: ["hydrant_sprinkler"] },
    fa: { vendors: ["fa1", "fa2"], items: ["FA-SDA-RAV", "FA-MDA-RAV", "FA-BASE-RAV", "FA-HTR-RAV", "FA-CM-RAV", "FA-SDA-HON", "FA-MDA-HON", "FA-BASE-HON", "FA-MCP-HON", "FA-PNA-RAV", "FA-RI-STD", "FA-BAT-EXI", "FA-ISO-RAV"], projSystems: ["fire_alarm"] },
    cables: { vendors: ["cable1", "fa2"], items: ["FA-CBL2-POL", "FA-CBL2-LAP", "FA-FSC-POL", "HS-CBL4C", "GN-CBL-3C25CU", "FA-CBL6-POL"], projSystems: ["fire_alarm", "hydrant_sprinkler"] },
    ext: { vendors: ["ext1", "ext2"], items: ["EXN-ABC6-SFX", "EXN-ABC4-SFX", "EXN-CO245-SFX", "EXN-CO22-CHK", "EXN-ABC6-CHK", "EXN-CA2-SFX", "EXN-FOAM9-SFX", "SP-ZBA", "SP-WSH", "SP-NOZ"], projSystems: [] },
    pumps: { vendors: ["pumps1"], items: ["HS-PSW", "HS-EPNL", "GN-PMP-JK180", "HS-PG"], projSystems: ["hydrant_sprinkler"] },
  };
  const CAT_SEQ = ["pipes", "fa", "valves", "ext", "pipes", "cables", "hydrant", "fa", "pipes", "pumps"];
  const purchaseQty = (it: SeedItem) => {
    if (it.uom === "Mtr") return /cable|Cable/.test(it.groupName + it.name) ? randInt(2, 10) * 50 : randInt(5, 40) * 6;
    const p = it.listPrice ?? 0;
    if (p >= 50000) return 1;
    if (p >= 5000) return randInt(1, 6);
    if (/Detector|Base|Sprinkler|Washer/i.test(it.groupName)) return randInt(2, 12) * 10;
    return randInt(4, 24);
  };
  type PILine = { itemCode: string; qty: number; rate: number; gstRate: number; amount: number };
  type PIBuilt = {
    cat: string; vendorKey: string; invoiceNo: string; invoiceDate: string; dueDate: string; projectKey: string | null;
    lines: PILine[]; subtotal: number; taxAmount: number; total: number; paidAmount: number; id?: number;
  };
  const vendorCounters = new Map<string, number>();
  const pis: PIBuilt[] = [];
  const N_PI = 40;
  for (let i = 0; i < N_PI; i++) {
    let da = Math.round(910 * (1 - i / (N_PI - 1))) + randInt(-5, 5);
    da = Math.max(2, Math.min(912, da));
    if (i === N_PI - 1) da = 2;
    const cat = i === N_PI - 1 ? "pipes" : i === N_PI - 2 ? "fa" : CAT_SEQ[i % CAT_SEQ.length];
    const pool = POOLS[cat];
    const vendorKey = pool.vendors[i % pool.vendors.length];
    const vend = V.get(vendorKey)!.v;
    const invoiceDate = ago(da);
    // project-linked material?
    let projectKey: string | null = null;
    const candidates = projects.filter((pr) => pr.startDate <= invoiceDate && pr.endDate >= invoiceDate
      && pool.projSystems.includes(TPL.get(pr.q.spec.tpl)!.t.system === "fire_alarm" ? "fire_alarm" : "hydrant_sprinkler"));
    if (candidates.length && rng() < 0.6) projectKey = pick(candidates).p.q;
    const nLines = cat === "pumps" ? randInt(2, 3) : randInt(3, 5);
    const codes = [...pool.items].sort(() => rng() - 0.5).slice(0, nLines);
    const lines: PILine[] = codes.map((code) => {
      const it = item(code);
      const qty = purchaseQty(it);
      const rate = Math.round(costAt(it, da, vend.priceFactor, rand(-0.025, 0.025)) * 100) / 100;
      const amount = round2(qty * rate);
      return { itemCode: code, qty, rate, gstRate: it.gstRate, amount };
    });
    const subtotal = round2(lines.reduce((a, l) => a + l.amount, 0));
    const taxAmount = round2(lines.reduce((a, l) => a + (l.amount * l.gstRate) / 100, 0));
    const total = round2(subtotal + taxAmount);
    const dueDate = addDays(invoiceDate, vend.paymentTermsDays);
    const f = fy(invoiceDate);
    const vc = (vendorCounters.get(vendorKey) ?? randInt(100, 400)) + randInt(3, 40);
    vendorCounters.set(vendorKey, vc);
    const dueAgo = daysAgoOf(dueDate);
    let paidAmount = 0;
    if (dueAgo > 150) paidAmount = total;
    else if (dueAgo > 0) paidAmount = i % 3 === 0 ? round2(total * 0.5) : i % 3 === 1 ? 0 : total; // some overdue unpaid / part-paid
    else paidAmount = i % 4 === 0 ? round2(total * 0.3) : 0;
    pis.push({ cat, vendorKey, invoiceNo: `${vend.invoicePrefix}/${f}/${pad(vc, 4)}`, invoiceDate, dueDate, projectKey, lines, subtotal, taxAmount, total, paidAmount });
  }
  // every started project gets at least one direct-to-site material invoice
  for (const pr of projects) {
    if (pis.some((p) => p.projectKey === pr.p.q)) continue;
    const sys = TPL.get(pr.q.spec.tpl)!.t.system === "fire_alarm" ? "fire_alarm" : "hydrant_sprinkler";
    const cand = pis.find((p) => !p.projectKey && p.invoiceDate >= pr.startDate && p.invoiceDate <= pr.endDate && POOLS[p.cat].projSystems.includes(sys));
    if (cand) cand.projectKey = pr.p.q;
  }
  // one invoice due within the payables lead window (5 days) for the demo
  {
    const last = pis[pis.length - 4];
    last.paidAmount = 0;
    last.dueDate = day(3);
  }
  const piIds = await db.insert(s.purchaseInvoices).values(pis.map((p) => ({
    vendorId: V.get(p.vendorKey)!.id, invoiceNo: p.invoiceNo, invoiceDate: p.invoiceDate, dueDate: p.dueDate,
    projectId: p.projectKey ? PRJ.get(p.projectKey)!.id : null, subtotal: p.subtotal, taxAmount: p.taxAmount, total: p.total,
    paidAmount: p.paidAmount, status: "posted", createdBy: U.purchase, createdAt: at(p.invoiceDate, 12),
    notes: p.projectKey ? `Direct to site, ${PRJ.get(p.projectKey)!.code}` : null,
  }))).returning({ id: s.purchaseInvoices.id });
  pis.forEach((p, i) => (p.id = piIds[i].id));

  const piLineRows: (typeof s.purchaseInvoiceLines.$inferInsert)[] = [];
  const phRows: (typeof s.priceHistory.$inferInsert)[] = [];
  const vendorItem = new Map<string, { vendorId: number; itemId: number; lastRate: number; lastDate: string; leadTimeDays: number }>();
  const lastPurchase = new Map<number, { rate: number; date: string; vendorId: number }>();
  const payRows: (typeof s.payments.$inferInsert)[] = [];
  for (const p of pis) {
    const vendorId = V.get(p.vendorKey)!.id;
    const projectId = p.projectKey ? PRJ.get(p.projectKey)!.id : null;
    for (const l of p.lines) {
      const it = item(l.itemCode);
      piLineRows.push({ invoiceId: p.id!, itemId: it.id, description: it.name, qty: l.qty, rate: l.rate, gstRate: l.gstRate, amount: l.amount });
      phRows.push({ itemId: it.id, kind: "purchase", rate: l.rate, date: p.invoiceDate, vendorId, refType: "purchase_invoice", refId: p.id!, qty: l.qty });
      const vk = `${vendorId}:${it.id}`;
      const prev = vendorItem.get(vk);
      if (!prev || prev.lastDate <= p.invoiceDate) {
        vendorItem.set(vk, { vendorId, itemId: it.id, lastRate: l.rate, lastDate: p.invoiceDate, leadTimeDays: V.get(p.vendorKey)!.v.leadTimeDays });
      }
      const lp = lastPurchase.get(it.id);
      if (!lp || lp.date <= p.invoiceDate) lastPurchase.set(it.id, { rate: l.rate, date: p.invoiceDate, vendorId });
      stockRows.push({
        itemId: it.id, qty: l.qty, type: "purchase_in", rate: l.rate, refType: "purchase_invoice", refId: p.id!,
        date: p.invoiceDate, createdBy: U.store, createdAt: at(p.invoiceDate, 13),
      });
      if (projectId) {
        stockRows.push({
          itemId: it.id, qty: -l.qty, type: "issue_project", rate: l.rate, projectId, refType: "purchase_invoice", refId: p.id!,
          date: p.invoiceDate, notes: "Delivered direct to site", createdBy: U.store, createdAt: at(p.invoiceDate, 14),
        });
      }
    }
    if (p.paidAmount > 0) {
      const payDate = minDate(addDays(p.invoiceDate, Math.max(7, V.get(p.vendorKey)!.v.paymentTermsDays - 3)), ago(1));
      payRows.push({
        direction: "out", vendorId, purchaseInvoiceId: p.id!, amount: p.paidAmount, date: payDate, mode: pick(["bank", "bank", "cheque", "upi"]),
        reference: `UTR${String(Math.floor(rng() * 1e10)).padStart(10, "0")}`, createdBy: U.accounts, createdAt: at(payDate, 15),
      });
    }
  }
  await batched(piLineRows, (c) => db.insert(s.purchaseInvoiceLines).values(c).returning({ id: s.purchaseInvoiceLines.id }));
  await batched(phRows, (c) => db.insert(s.priceHistory).values(c).returning({ id: s.priceHistory.id }));
  await batched([...vendorItem.values()], (c) => db.insert(s.vendorItems).values(c).returning({ id: s.vendorItems.id }));
  for (const [itemId, lp] of lastPurchase) {
    await db.update(s.items).set({ lastPurchaseRate: lp.rate, lastPurchaseDate: lp.date, lastPurchaseVendorId: lp.vendorId }).where(eq(s.items.id, itemId));
  }

  // ---------------------------------------------------------------- sales orders (customer POs), deliveries
  type SOLine = {
    itemId: number; description: string; qty: number; deliveredQty: number; invoicedQty: number; uom: string; rate: number;
    deliveryStatus: string; expectedDate: string; remarks: string | null; deliveryIdx: number | null; id?: number;
  };
  type SOBuilt = {
    key: string; q: QBuilt; projectKey: string | null; orderDate: string; poNo: string; lines: SOLine[];
    deliveryDates: string[]; id?: number; number?: string; status?: string; total?: number;
  };
  // plan: [quoteKey, orderDaysAgo, deliveryDaysAgo[], per-line outcome fn]
  type Outcome = { status: string; frac: number; dIdx: number | null; expected: string };
  const SO_PLAN: { q: string; order: number; deliveries: number[]; outcome: (i: number, n: number) => Outcome }[] = [
    { q: "w1", order: 275, deliveries: [240, 200], outcome: (i, n) => ({ status: "delivered", frac: 1, dIdx: i < Math.ceil(n * 0.6) ? 0 : 1, expected: ago(245) }) },
    { q: "w2", order: 185, deliveries: [150, 120], outcome: (i, n) => (i === Math.min(3, n - 1)
      ? { status: "pending", frac: 0, dIdx: null, expected: ago(100) } // the "1 of 10 lines missed" case
      : { status: "delivered", frac: 1, dIdx: i % 2, expected: ago(155) }) },
    { q: "w3", order: 145, deliveries: [120], outcome: (i) => [
      { status: "delivered", frac: 1, dIdx: 0, expected: ago(125) },
      { status: "delivered", frac: 1, dIdx: 0, expected: ago(125) },
      { status: "partial", frac: 0.5, dIdx: 0, expected: ago(20) },
      { status: "in_transit", frac: 0, dIdx: null, expected: ago(20) },
      { status: "ordered", frac: 0, dIdx: null, expected: day(10) },
    ][i % 5] },
    { q: "w4", order: 70, deliveries: [50], outcome: (i) => [
      { status: "delivered", frac: 1, dIdx: 0, expected: ago(52) },
      { status: "delivered", frac: 1, dIdx: 0, expected: ago(52) },
      { status: "pending", frac: 0, dIdx: null, expected: day(2) },
      { status: "in_transit", frac: 0, dIdx: null, expected: ago(5) },
    ][i % 4] },
    { q: "w5", order: 35, deliveries: [26], outcome: () => ({ status: "delivered", frac: 1, dIdx: 0, expected: ago(27) }) },
    { q: "w6", order: 20, deliveries: [15], outcome: (i, n) => (i === n - 1
      ? { status: "pending", frac: 0, dIdx: null, expected: ago(3) }
      : { status: "delivered", frac: 1, dIdx: 0, expected: ago(16) }) },
  ];
  const sos: SOBuilt[] = SO_PLAN.map((pl, k) => {
    const q = Q.get(pl.q)!;
    const src = q.lines.filter((l) => l.itemId).slice(0, 10);
    const lines: SOLine[] = src.map((l, i) => {
      const o = pl.outcome(i, src.length);
      let delivered = o.frac >= 1 ? l.qty : Math.floor(l.qty * o.frac);
      let status = o.status;
      if (status === "partial" && (delivered <= 0 || delivered >= l.qty)) { delivered = l.qty; status = "delivered"; }
      return {
        itemId: l.itemId!, description: ITEM_BY_ID.get(l.itemId!)!.name, qty: l.qty, deliveredQty: delivered, invoicedQty: 0,
        uom: l.uom, rate: l.supplyRate, deliveryStatus: status, expectedDate: status === "delivered" ? o.expected : o.expected,
        remarks: status === "in_transit" ? "Dispatched by vendor, LR awaited" : status === "pending" ? "Material not yet ordered from vendor" : null,
        deliveryIdx: delivered > 0 ? o.dIdx : null,
      };
    });
    return {
      key: pl.q, q, projectKey: PRJ.has(pl.q) ? pl.q : null, orderDate: ago(pl.order), poNo: `PO/${4500100000 + k * 7919 + 31}`,
      lines, deliveryDates: pl.deliveries.map((d) => ago(d)),
    };
  });

  // sales invoices plan (computed before inserting order lines so invoicedQty is known)
  type SILine = { soLine: SOLine | null; itemId: number | null; description: string; qty: number; rate: number; gstRate: number; amount: number };
  type SIBuilt = {
    customer: number; so: SOBuilt | null; projectKey: string | null; invoiceDate: string; dueDate: string; lines: SILine[];
    pay: number; payAfterDays: number; reminderCount: number; refillGroup?: string; id?: number; number?: string;
    subtotal?: number; taxAmount?: number; total?: number; paidAmount?: number;
  };
  const sis: SIBuilt[] = [];
  const soInvoice = (so: SOBuilt, filter: (l: SOLine, i: number) => boolean, invoiceDaysAgo: number, pay: number, payAfterDays: number, reminderCount = 0) => {
    const cust = so.q.spec.cust;
    const invoiceDate = ago(invoiceDaysAgo);
    const lines: SILine[] = so.lines.filter((l, i) => l.deliveredQty - l.invoicedQty > 0 && filter(l, i)).map((l) => {
      const qty = l.deliveredQty - l.invoicedQty;
      l.invoicedQty += qty;
      return { soLine: l, itemId: l.itemId, description: l.description, qty, rate: l.rate, gstRate: 18, amount: round2(qty * l.rate) };
    });
    sis.push({ customer: cust, so, projectKey: so.projectKey, invoiceDate, dueDate: addDays(invoiceDate, DEMO_CUSTOMERS[cust].paymentTermsDays), lines, pay, payAfterDays, reminderCount });
  };
  const SO = new Map(sos.map((x) => [x.key, x]));
  soInvoice(SO.get("w1")!, (l) => l.deliveryIdx === 0, 235, 1, 28);
  soInvoice(SO.get("w1")!, () => true, 195, 1, 32);
  soInvoice(SO.get("w2")!, () => true, 80, 0.4, 30, 1);            // overdue 35 days, part-paid
  soInvoice(SO.get("w3")!, () => true, 100, 0, 0, 2);              // overdue 70 days, unpaid
  soInvoice(SO.get("w5")!, (_l, i) => i % 2 === 0, 25, 1, 10);     // paid
  soInvoice(SO.get("w5")!, () => true, 25, 0, 0);                  // overdue 10 days
  soInvoice(SO.get("w6")!, () => true, 14, 0.5, 5);                // part-paid, not yet due

  // ---------------------------------------------------------------- extinguisher assets & refill invoices
  type ExtType = { label: string; code: string; interval: number };
  const EXT_TYPES: ExtType[] = [
    { label: "ABC 6 Kg", code: "ABC6", interval: 12 }, { label: "ABC 4 Kg", code: "ABC4", interval: 12 },
    { label: "ABC 9 Kg", code: "ABC9", interval: 12 }, { label: "CO2 4.5 Kg", code: "CO245", interval: 12 },
    { label: "CO2 2 Kg", code: "CO22", interval: 12 }, { label: "CO2 9 Kg", code: "CO29", interval: 12 },
    { label: "Foam 9 Ltr", code: "FOAM9", interval: 12 }, { label: "Clean Agent 2 Kg", code: "CA2", interval: 36 },
    { label: "Clean Agent 4 Kg", code: "CA4", interval: 36 }, { label: "ABC 25 Kg", code: "ABC25", interval: 12 },
  ];
  const LOCS = ["Main Plant, Bay 1", "Main Plant, Bay 2", "Admin Block, Ground Floor", "Admin Block, First Floor", "Canteen / Kitchen",
    "DG Room", "Electrical Room / LT Panel", "Stores", "Security Gate", "Server Room", "Compressor Room", "Paint Shop", "Lift Machine Room", "Basement Parking"];
  type AssetBuilt = {
    customer: number; location: string; t: ExtType; make: string; qty: number; installDate: string; lastRefillDate: string;
    nextDueDate: string; hptDueDate: string | null; serialNo: string; group: string; id?: number;
  };
  const assets: AssetBuilt[] = [];
  // groups: [customerIdx, groupKey, count, function(i) -> nextDue offset (days from today) OR fixed lastRefill daysAgo]
  const EXT_GROUPS: { cust: number; key: string; n: number; lastRefillAgo?: number; dueOffset?: (i: number) => number }[] = [
    { cust: 1, key: "R1", n: 10, lastRefillAgo: 200 },                                   // refilled 200 days ago (invoice R1, paid)
    { cust: 6, key: "R2", n: 10, lastRefillAgo: 40 },                                    // refilled 40 days ago (invoice R2, overdue)
    { cust: 7, key: "R3", n: 10, lastRefillAgo: 12 },                                    // refilled 12 days ago (invoice R3, issued)
    { cust: 0, key: "OVD", n: 10, dueOffset: (i) => (i < 6 ? -(3 + i * 5) : 40 + i * 20) },  // 6 overdue
    { cust: 2, key: "DUE", n: 10, dueOffset: (i) => (i < 8 ? i + 1 : 120 + i * 10) },        // 8 due within 10 days
    { cust: 8, key: "MIX", n: 10, dueOffset: (i) => 60 + i * 27 },
  ];
  let serial = 41000;
  for (const g of EXT_GROUPS) {
    for (let i = 0; i < g.n; i++) {
      const t = i === 9 && g.key === "MIX" ? EXT_TYPES[7] : i === 8 && g.key !== "R2" ? EXT_TYPES[8] : EXT_TYPES[i % 8];
      const make = rng() < 0.6 ? "Safex" : "Chakraa";
      let lastRefillDate: string, nextDueDate: string;
      if (g.lastRefillAgo != null) {
        lastRefillDate = ago(g.lastRefillAgo);
        nextDueDate = addMonths(lastRefillDate, t.interval);
      } else {
        nextDueDate = day(g.dueOffset!(i));
        lastRefillDate = addMonths(nextDueDate, -t.interval);
      }
      const installDate = addMonths(lastRefillDate, -12 * randInt(1, 4));
      const isCo2 = t.code.startsWith("CO2");
      const hptDueDate = isCo2 || i % 4 === 0 ? addMonths(installDate, 60) : null;
      assets.push({
        customer: g.cust, location: LOCS[(i + g.cust) % LOCS.length], t, make, qty: randInt(1, 4), installDate, lastRefillDate,
        nextDueDate, hptDueDate, serialNo: `${make === "Safex" ? "SFX" : "CHK"}-${serial++}`, group: g.key,
      });
    }
  }
  const REFILL_INV: { group: string; daysAgo: number; pay: number; payAfterDays: number }[] = [
    { group: "R1", daysAgo: 200, pay: 1, payAfterDays: 20 },
    { group: "R2", daysAgo: 40, pay: 0, payAfterDays: 0 },
    { group: "R3", daysAgo: 12, pay: 0, payAfterDays: 0 },
  ];
  const refillCode = (a: AssetBuilt) => `EXR-${a.t.code}-${a.make === "Safex" ? "SFX" : "CHK"}`;
  for (const r of REFILL_INV) {
    const grp = assets.filter((a) => a.group === r.group);
    const byCode = new Map<string, number>();
    for (const a of grp) byCode.set(refillCode(a), (byCode.get(refillCode(a)) ?? 0) + a.qty);
    const invoiceDate = ago(r.daysAgo);
    const lines: SILine[] = [...byCode.entries()].map(([code, qty]) => {
      const it = item(code);
      const rate = sellAt(it, r.daysAgo);
      return { soLine: null, itemId: it.id, description: it.name, qty, rate, gstRate: 18, amount: round2(qty * rate) };
    });
    const cust = grp[0].customer;
    sis.push({
      customer: cust, so: null, projectKey: null, invoiceDate, dueDate: addDays(invoiceDate, DEMO_CUSTOMERS[cust].paymentTermsDays),
      lines, pay: r.pay, payAfterDays: r.payAfterDays, reminderCount: r.group === "R2" ? 1 : 0, refillGroup: r.group,
    });
  }

  // ---------------------------------------------------------------- insert sales orders + lines + deliveries
  for (const so of sos) {
    const f = fy(so.orderDate);
    so.number = `LBE/SO/${f}/${pad(nextSeq(`sales_order:${f}`), 4)}`;
    const allDone = so.lines.every((l) => l.deliveredQty >= l.qty);
    const any = so.lines.some((l) => l.deliveredQty > 0);
    so.status = allDone ? "delivered" : any ? "partial" : "open";
    so.total = round2(so.lines.reduce((a, l) => a + l.qty * l.rate, 0));
  }
  const soIds = await db.insert(s.salesOrders).values(sos.map((so) => ({
    number: so.number!, customerId: C(so.q.spec.cust), customerPoNumber: so.poNo, customerPoDate: addDays(so.orderDate, -1),
    quotationId: so.q.id!, projectId: so.projectKey ? PRJ.get(so.projectKey)!.id : null, status: so.status!, orderDate: so.orderDate,
    expectedDelivery: addDays(so.orderDate, 21), total: so.total!, createdBy: U.sales, createdAt: at(so.orderDate, 12),
    notes: so.projectKey ? null : "Supply only, no installation.",
  }))).returning({ id: s.salesOrders.id });
  sos.forEach((so, i) => (so.id = soIds[i].id));
  const solFlat = sos.flatMap((so) => so.lines.map((l, i) => ({ so, l, i })));
  const solIds = await batched(solFlat.map(({ so, l, i }) => ({
    orderId: so.id!, sortOrder: i + 1, itemId: l.itemId, description: l.description, qty: l.qty, deliveredQty: l.deliveredQty,
    invoicedQty: l.invoicedQty, uom: l.uom, rate: l.rate, deliveryStatus: l.deliveryStatus, expectedDate: l.expectedDate, remarks: l.remarks,
  })), (c) => db.insert(s.salesOrderLines).values(c).returning({ id: s.salesOrderLines.id }));
  solFlat.forEach(({ l }, i) => (l.id = solIds[i].id));

  type DelBuilt = { so: SOBuilt; date: string; lines: SOLine[]; id?: number; number?: string };
  const dels: DelBuilt[] = [];
  for (const so of sos) {
    so.deliveryDates.forEach((date, di) => {
      const lines = so.lines.filter((l) => l.deliveryIdx === di && l.deliveredQty > 0);
      if (lines.length) dels.push({ so, date, lines });
    });
  }
  dels.sort((a, b) => (a.date < b.date ? -1 : 1));
  for (const d of dels) {
    const f = fy(d.date);
    d.number = `LBE/DC/${f}/${pad(nextSeq(`delivery:${f}`), 4)}`;
  }
  const delIds = await db.insert(s.deliveries).values(dels.map((d, i) => ({
    number: d.number!, orderId: d.so.id!, date: d.date, vehicleNo: `TN 70 ${["AB", "AK", "BC", "AZ"][i % 4]} ${pad(1200 + i * 377 % 8000, 4)}`,
    receivedBy: DEMO_CUSTOMERS[d.so.q.spec.cust].contactPerson.split(" (")[0], createdBy: U.store, createdAt: at(d.date, 16),
  }))).returning({ id: s.deliveries.id });
  dels.forEach((d, i) => (d.id = delIds[i].id));
  await batched(dels.flatMap((d) => d.lines.map((l) => ({ deliveryId: d.id!, orderLineId: l.id!, qty: l.deliveredQty }))),
    (c) => db.insert(s.deliveryLines).values(c).returning({ id: s.deliveryLines.id }));
  // supply-only order ships from stock
  for (const d of dels.filter((x) => !x.so.projectKey)) {
    for (const l of d.lines) {
      stockRows.push({
        itemId: l.itemId, qty: -l.deliveredQty, type: "sale_out", rate: costAt(ITEM_BY_ID.get(l.itemId)!, daysAgoOf(d.date)),
        refType: "delivery", refId: d.id!, date: d.date, createdBy: U.store, createdAt: at(d.date, 15),
      });
    }
  }

  // ---------------------------------------------------------------- insert sales invoices, lines, payments
  sis.sort((a, b) => (a.invoiceDate < b.invoiceDate ? -1 : a.invoiceDate > b.invoiceDate ? 1 : 0));
  const inRows: (typeof s.payments.$inferInsert)[] = [];
  for (const si of sis) {
    const f = fy(si.invoiceDate);
    si.number = `LBE/INV/${f}/${pad(nextSeq(`sales_invoice:${f}`), 4)}`;
    si.subtotal = round2(si.lines.reduce((a, l) => a + l.amount, 0));
    si.taxAmount = round2(si.lines.reduce((a, l) => a + (l.amount * l.gstRate) / 100, 0));
    si.total = round2(si.subtotal + si.taxAmount);
    si.paidAmount = si.pay >= 1 ? si.total : round2(si.total * si.pay);
  }
  const siIds = await db.insert(s.salesInvoices).values(sis.map((si) => ({
    number: si.number!, customerId: C(si.customer), orderId: si.so?.id ?? null, projectId: si.projectKey ? PRJ.get(si.projectKey)!.id : null,
    invoiceDate: si.invoiceDate, dueDate: si.dueDate, subtotal: si.subtotal!, taxAmount: si.taxAmount!, total: si.total!,
    paidAmount: si.paidAmount!, status: si.paidAmount! >= si.total! ? "paid" : si.paidAmount! > 0 ? "partially_paid" : "issued",
    reminderCount: si.reminderCount, lastReminderAt: si.reminderCount > 0 ? at(ago(8), 9) : null,
    notes: si.refillGroup ? "Extinguisher refilling service" : null, createdBy: U.accounts, createdAt: at(si.invoiceDate, 17),
  }))).returning({ id: s.salesInvoices.id });
  sis.forEach((si, i) => (si.id = siIds[i].id));
  await batched(sis.flatMap((si) => si.lines.map((l) => ({
    invoiceId: si.id!, orderLineId: l.soLine?.id ?? null, itemId: l.itemId, description: l.description, qty: l.qty, rate: l.rate,
    gstRate: l.gstRate, amount: l.amount,
  }))), (c) => db.insert(s.salesInvoiceLines).values(c).returning({ id: s.salesInvoiceLines.id }));
  const saleHist: (typeof s.priceHistory.$inferInsert)[] = [];
  const lastSale = new Map<number, { rate: number; date: string }>();
  for (const si of sis) {
    if (si.paidAmount! > 0) {
      const d = minDate(addDays(si.invoiceDate, si.payAfterDays), ago(1));
      inRows.push({
        direction: "in", customerId: C(si.customer), salesInvoiceId: si.id!, amount: si.paidAmount!, date: d,
        mode: pick(["bank", "bank", "cheque", "upi"]), reference: `NEFT${String(Math.floor(rng() * 1e9)).padStart(9, "0")}`,
        createdBy: U.accounts, createdAt: at(d, 12),
      });
    }
    for (const l of si.lines) {
      if (!l.itemId) continue;
      saleHist.push({ itemId: l.itemId, kind: "sale", rate: l.rate, date: si.invoiceDate, customerId: C(si.customer), refType: "sales_invoice", refId: si.id!, qty: l.qty });
      const ls = lastSale.get(l.itemId);
      if (!ls || ls.date <= si.invoiceDate) lastSale.set(l.itemId, { rate: l.rate, date: si.invoiceDate });
    }
  }
  await batched([...payRows, ...inRows], (c) => db.insert(s.payments).values(c).returning({ id: s.payments.id }));
  await batched(saleHist, (c) => db.insert(s.priceHistory).values(c).returning({ id: s.priceHistory.id }));
  for (const [itemId, ls] of lastSale) {
    await db.update(s.items).set({ lastSaleRate: ls.rate, lastSaleDate: ls.date }).where(eq(s.items.id, itemId));
  }

  // ---------------------------------------------------------------- extinguisher assets + refill history
  const assetIds = await batched(assets.map((a) => ({
    customerId: C(a.customer), location: a.location, extType: a.t.label, make: a.make, serialNo: a.serialNo, qty: a.qty,
    installDate: a.installDate, lastRefillDate: a.lastRefillDate, refillIntervalMonths: a.t.interval, nextDueDate: a.nextDueDate,
    hptDueDate: a.hptDueDate, status: "active",
  })), (c) => db.insert(s.extinguisherAssets).values(c).returning({ id: s.extinguisherAssets.id }));
  assets.forEach((a, i) => (a.id = assetIds[i].id));
  const refillInvByGroup = new Map(sis.filter((x) => x.refillGroup).map((x) => [x.refillGroup!, x]));
  const rsRows: (typeof s.refillServices.$inferInsert)[] = [];
  for (const a of assets) {
    const it = item(refillCode(a));
    const inv = refillInvByGroup.get(a.group);
    let d = a.lastRefillDate;
    let first = true;
    while (d > a.installDate && daysAgoOf(d) >= 0) {
      const rate = inv && first ? inv.lines.find((l) => l.itemId === it.id)!.rate : sellAt(it, daysAgoOf(d));
      rsRows.push({
        assetId: a.id!, date: d, kind: "refill", salesInvoiceId: inv && first ? inv.id! : null, amount: round2(rate * a.qty),
        notes: first ? "Refilled & pressure checked" : "Annual refilling", userId: U.engineer, createdAt: at(d, 15),
      });
      first = false;
      d = addMonths(d, -a.t.interval);
    }
    if (a.hptDueDate && a.installDate < ago(365)) {
      rsRows.push({ assetId: a.id!, date: addMonths(a.installDate, 1), kind: "service", amount: 0, notes: "Installed & commissioned; HPT certificate filed", userId: U.engineer });
    }
  }
  await batched(rsRows, (c) => db.insert(s.refillServices).values(c).returning({ id: s.refillServices.id }));

  // ---------------------------------------------------------------- expenses & allocations (~25)
  const EXP_CATS: { cat: string; min: number; max: number; desc: string[]; paidTo: string[] }[] = [
    { cat: "petrol", min: 600, max: 3200, desc: ["Bike petrol for site visits", "Car diesel, Hosur ↔ site", "Petrol for material pickup"], paidTo: ["HP Petrol Bunk, Hosur", "Indian Oil, Attibele", "Bharat Petroleum, Krishnagiri"] },
    { cat: "lodging", min: 1800, max: 6500, desc: ["Lodging for installation team (2 nights)", "Room rent for commissioning visit"], paidTo: ["Hotel Hills Inn, Hosur", "Sri Lakshmi Residency, Electronic City"] },
    { cat: "food", min: 350, max: 2400, desc: ["Team lunch at site", "Food for labour (overtime)"], paidTo: ["Saravana Bhavan", "Local mess"] },
    { cat: "labour", min: 3000, max: 18000, desc: ["Contract welders (3 days)", "Helpers for pipe shifting", "Electrician for cable termination"], paidTo: ["Muthu Labour Contractor", "Rajan Welding Works", "Daily wage helpers"] },
    { cat: "transport", min: 1500, max: 9000, desc: ["Tempo hire for pipes to site", "Crane hire for pump unloading", "Courier of detectors"], paidTo: ["Sri Vinayaga Transports", "Hosur Crane Service", "DTDC Hosur"] },
  ];
  type ExpBuilt = { date: string; cat: string; amount: number; desc: string; paidTo: string; user: string; status: string; allocs: { projectId: number; amount: number }[] };
  const exps: ExpBuilt[] = [];
  for (let i = 0; i < 25; i++) {
    const da = i < 20 ? Math.round(195 - i * 9.5) : [9, 6, 3, 1, 0][i - 20];
    const date = ago(da);
    const active = projects.filter((pr) => pr.startDate <= date && addDays(pr.endDate, 20) >= date);
    const pool = active.length ? active : [projects[projects.length - 1]];
    const c = EXP_CATS[i % EXP_CATS.length];
    const amount = Math.round(rand(c.min, c.max) / 10) * 10;
    const status = i >= 20 ? "pending" : i === 13 ? "rejected" : "approved";
    const split = pool.length >= 2 && (i % 6 === 2 || i === 21);
    let allocs: { projectId: number; amount: number }[];
    if (split) {
      const [p1, p2] = [...pool].sort(() => rng() - 0.5).slice(0, 2);
      const a1 = Math.round(amount * 0.6);
      allocs = [{ projectId: p1.id, amount: a1 }, { projectId: p2.id, amount: amount - a1 }];
    } else allocs = [{ projectId: pick(pool).id, amount }];
    exps.push({ date, cat: c.cat, amount, desc: split ? `${pick(c.desc)} (covered 2 sites)` : pick(c.desc), paidTo: pick(c.paidTo), user: i % 2 ? "engineer" : "engineer2", status, allocs: status === "rejected" ? [] : allocs });
  }
  const expIds = await db.insert(s.expenses).values(exps.map((e) => ({
    voucherNo: `EXP-${pad(nextSeq("expense"), 4)}`, date: e.date, category: e.cat, amount: e.amount, description: e.desc,
    paidTo: e.paidTo, billRef: `B-${randInt(1000, 9999)}`, userId: U[e.user], status: e.status,
    approvedBy: e.status === "pending" ? null : U.admin, createdAt: at(e.date, 19),
  }))).returning({ id: s.expenses.id });
  const allocRows = exps.flatMap((e, i) => e.allocs.map((a) => ({ expenseId: expIds[i].id, projectId: a.projectId, amount: a.amount })));
  if (allocRows.length) await db.insert(s.expenseAllocations).values(allocRows);

  // ---------------------------------------------------------------- stock movements & allocations
  stockRows.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  await batched(stockRows, (c) => db.insert(s.stockMovements).values(c).returning({ id: s.stockMovements.id }));
  const p4 = PRJ.get("w4")!, p2 = PRJ.get("w2")!;
  const so6 = SO.get("w6")!;
  await db.insert(s.stockAllocations).values([
    { itemId: item("FA-SDA-RAV").id, qty: 20, customerId: C(p2.q.spec.cust), projectId: p2.id, status: "reserved", notes: "Reserved for Plant 2 (phase 2 detectors)" },
    { itemId: item("FA-BASE-RAV").id, qty: 20, customerId: C(p2.q.spec.cust), projectId: p2.id, status: "reserved", notes: "Bases for phase 2" },
    { itemId: item("EXN-ABC6-SFX").id, qty: 6, customerId: C(so6.q.spec.cust), orderId: so6.id!, status: "reserved", notes: "Balance qty against customer PO" },
    { itemId: item("HS-SPR-PEN").id, qty: 40, customerId: C(p4.q.spec.cust), projectId: p4.id, status: "consumed", notes: "Issued to site" },
  ]);

  // ---------------------------------------------------------------- meeting notes
  const [note] = await db.insert(s.meetingNotes).values({
    title: KICKOFF_NOTE.title, meetingDate: KICKOFF_NOTE.meetingDate, attendees: KICKOFF_NOTE.attendees, summary: KICKOFF_NOTE.summary,
    decisions: KICKOFF_NOTE.decisions, actionItems: KICKOFF_NOTE.actionItems, openQuestions: KICKOFF_NOTE.openQuestions,
    transcript: KICKOFF_TRANSCRIPT, version: 1, updatedBy: U.admin,
  }).returning({ id: s.meetingNotes.id });
  await db.insert(s.meetingNoteRevisions).values({
    noteId: note.id, version: 1, changeSummary: "Initial notes from kickoff transcript", updatedBy: U.admin,
    snapshot: {
      title: KICKOFF_NOTE.title, meetingDate: KICKOFF_NOTE.meetingDate, attendees: KICKOFF_NOTE.attendees, summary: KICKOFF_NOTE.summary,
      decisions: KICKOFF_NOTE.decisions, actionItems: KICKOFF_NOTE.actionItems, openQuestions: KICKOFF_NOTE.openQuestions,
    },
  });

  // ---------------------------------------------------------------- sequences (continue numbering after seeded docs)
  const curFy = fy(day(0));
  for (const k of ["quotation", "sales_order", "sales_invoice", "delivery"]) if (!seq.has(`${k}:${curFy}`)) seq.set(`${k}:${curFy}`, 0);
  if (!seq.has(`project:${T0.getFullYear()}`)) seq.set(`project:${T0.getFullYear()}`, 0);
  await db.insert(s.sequences).values([...seq.entries()].map(([key, value]) => ({ key, value })));
}
